INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('4a4a7f82-7cad-454b-8cd1-e30613bf14cf', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___Leaf_Mold', 'Passalora fulva', 'A fungal disease mainly occurring in greenhouse tomatoes with high humidity.', 'Medium', '["Pale yellow spots on upper leaf surface", "Olive-green velvety mold on underside", "Leaves curl and wither", "Mainly affects older leaves"]'::json, '["Improve ventilation", "Reduce humidity below 85%", "Apply chlorothalonil fungicide", "Remove infected leaves"]'::json, '["Maintain low greenhouse humidity", "Good air circulation", "Avoid leaf wetness", "Use resistant varieties"]'::json) ON CONFLICT (name) DO NOTHING;
INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('f2259ea7-b245-4e14-8563-af3717a272c8', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___Septoria_leaf_spot', 'Septoria lycopersici', 'A fungal disease causing numerous small spots with dark borders and gray centers.', 'Medium', '["Small circular spots with gray centers", "Dark brown borders on spots", "Lower leaves affected first", "Progressive defoliation upward"]'::json, '["Apply chlorothalonil or mancozeb", "Remove infected lower leaves", "Mulch to prevent splash", "Prune for air circulation"]'::json, '["Crop rotation", "Remove plant debris", "Mulching", "Avoid overhead irrigation"]'::json) ON CONFLICT (name) DO NOTHING;
INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('1159edbf-5b2d-4d7f-a09e-7112059f7ffe', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___Spider_mites Two-spotted_spider_mite', 'Tetranychus urticae', 'Tiny arachnid pests that feed on leaf cells, causing stippling and webbing.', 'Medium', '["Fine stippling on leaf surface", "Yellowing of leaves", "Fine webbing on undersides", "Leaf bronzing and drop"]'::json, '["Apply miticide (abamectin)", "Use insecticidal soap", "Release predatory mites", "Increase humidity around plants"]'::json, '["Monitor regularly with hand lens", "Keep plants well-watered", "Avoid dusty conditions", "Introduce beneficial predators"]'::json) ON CONFLICT (name) DO NOTHING;
INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('ddf85549-2df0-4ab6-8432-e347f4402fd7', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___Target_Spot', 'Corynespora cassiicola', 'A fungal disease producing concentric ring patterns on leaves.', 'Medium', '["Brown spots with concentric rings", "Spots may have yellow halo", "Affects leaves, stems, and fruit", "Progressive defoliation"]'::json, '["Apply azoxystrobin or chlorothalonil", "Remove infected leaves", "Improve air circulation", "Reduce leaf wetness"]'::json, '["Crop rotation", "Proper spacing", "Mulching", "Avoid wet foliage"]'::json) ON CONFLICT (name) DO NOTHING;
INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('4d11a0a9-8eb6-4f81-862f-6d570c009cf5', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___Tomato_Yellow_Leaf_Curl_Virus', 'Tomato yellow leaf curl virus (TYLCV)', 'A devastating viral disease transmitted by whiteflies, causing severe yield loss.', 'High', '["Upward curling of leaf margins", "Yellowing of young leaves", "Stunted plant growth", "Flower drop and reduced fruit set"]'::json, '["No cure \u2014 remove infected plants", "Control whitefly vector", "Use reflective mulch to repel whiteflies", "Apply imidacloprid for whitefly control"]'::json, '["Use TYLCV-resistant varieties", "Control whitefly populations", "Use insect-proof netting", "Remove infected plants immediately"]'::json) ON CONFLICT (name) DO NOTHING;
INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('83a5379b-7cf7-44df-9f74-79d550669ac4', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___Tomato_mosaic_virus', 'Tomato mosaic virus (ToMV)', 'A highly contagious viral disease spread by contact, tools, and infected seeds.', 'High', '["Light and dark green mosaic pattern", "Leaf curling and distortion", "Stunted growth", "Reduced and deformed fruit"]'::json, '["No cure \u2014 remove infected plants", "Disinfect tools with 10% bleach", "Wash hands with soap between plants", "Do not smoke near tomato plants (TMV in tobacco)"]'::json, '["Use virus-free seed", "Disinfect tools regularly", "Wash hands before handling plants", "Use resistant varieties"]'::json) ON CONFLICT (name) DO NOTHING;
INSERT INTO diseases (id, crop_id, name, scientific_name, description, severity, symptoms, remedies, prevention) VALUES ('a0feb0bd-9f0d-4b0c-b26b-33fdb33b673e', 'a97d6fad-d105-43fc-aeef-035e811e7522', 'Tomato___healthy', NULL, 'A healthy tomato leaf with no disease symptoms.', NULL, '[]'::json, '[]'::json, '["Proper staking", "Consistent watering", "Balanced fertilization", "Regular monitoring"]'::json) ON CONFLICT (name) DO NOTHING;
